122:     static clip_image_size calc_size_preserved_ratio(const clip_image_size & inp_size, const calc_size_opt & opts) {
123:         GGML_ASSERT(opts.align_size > 0);
124:         const int width  = inp_size.width;
125:         const int height = inp_size.height;
126:         if (width <= 0 || height <= 0) {
127:             return {0, 0};
128:         }
129: 
130:         auto round_by_factor = [f = opts.align_size](float x) { return static_cast<int>(std::round(x / static_cast<float>(f))) * f; };
131:         auto ceil_by_factor  = [f = opts.align_size](float x) { return static_cast<int>(std::ceil(x / static_cast<float>(f))) * f; };
132:         auto floor_by_factor = [f = opts.align_size](float x) { return static_cast<int>(std::floor(x / static_cast<float>(f))) * f; };
133: 
134:         int w_bar, h_bar;
135:         if (opts.longest_edge > 0) {
136:             const float scale = std::min(static_cast<float>(opts.longest_edge) / width,
137:                                           static_cast<float>(opts.longest_edge) / height);
138:             w_bar = ceil_by_factor(width  * scale);
139:             h_bar = ceil_by_factor(height * scale);
140:         } else {
141:             // always align up first
142:             w_bar = std::max(opts.align_size, round_by_factor(width));
143:             h_bar = std::max(opts.align_size, round_by_factor(height));
144:         }
145: 
146:         if (opts.max_pixels > 0 && h_bar * w_bar > opts.max_pixels) {
147:             const auto beta = std::sqrt(static_cast<float>(height) * width / opts.max_pixels);
148:             h_bar = std::max(opts.align_size, floor_by_factor(height / beta));
149:             w_bar = std::max(opts.align_size, floor_by_factor(width  / beta));
150:         } else if (opts.min_pixels > 0 && h_bar * w_bar < opts.min_pixels) {
151:             const auto beta = std::sqrt(static_cast<float>(opts.min_pixels) / (static_cast<float>(height) * width));
152:             h_bar = ceil_by_factor(height * beta);
153:             w_bar = ceil_by_factor(width * beta);
154:         }
155: 
156:         return {w_bar, h_bar};

